{
  "@context": {
    "@language": "en",
    "@vocab": "https://schema.org/",
    "cr": "http://mlcommons.org/croissant/",
    "dct": "http://purl.org/dc/terms/",
    "sc": "https://schema.org/"
  },
  "@type": "cr:TaskProblem",
  "conformsTo": "http://mlcommons.org/croissant/1.0",
  "@id": "erasing-the-invisible-task",
  "name": "Erasing the Invisible",
  "description": "The task evaluates the robustness of invisible watermarking techniques embedded in AI-generated images against adversarial attacks. Participants must design methods to remove or degrade watermarks while preserving the visual quality of the images.",
  "paper_id": "neurips2024-erasing-the-invisible",

  "cr:input": [
    {
      "@type": "cr:FileObject",
      "name": "ETI_Competition_Data",
      "description": "A dataset of 300 AI-generated images per track (Beige-box and Black-box) embedded with invisible watermarks using various techniques. Features include `image_index` and `watermarked_image`. Example techniques: Gaussian Shading, StegaStamp, JigMark, PRC, StableSignature, Trufo.",
      "encodingFormat": "image/png",
      "contentUrl": "https://huggingface.co/furonghuang-lab/ETI_Competition_Data"
    }
  ],

  "cr:output": {
    "name": "predictions",
    "description": "A set of 300 attacked images in PNG format, corresponding to the input images. The goal is to reduce watermark detection scores (A) while minimizing image quality degradation (Q).",
    "cr:schema": {
      "@type": "cr:RecordSet",
      "name": "prediction_schema",
      "field": [
        {
          "@type": "cr:Field",
          "name": "attacked_image",
          "dataType": "sc:ImageObject",
          "description": "The attacked image in PNG format, corresponding to the input watermarked image."
        }
      ]
    }
  },

  "cr:implementation": {
    "cr:environment": {
      "language": "Python",
      "packages": ["torch", "onnxruntime-gpu", "transformers", "diffusers"]
    },
    "entryPoint": "solution.py",
    "interface": "predict(input_dir, output_dir)"
  },

  "cr:evaluation": {
    "primaryMetric": "Final Score (Euclidean distance in Q-A space)",
    "metrics": [
      "Final Score (Euclidean distance in Q-A space)",
      "Watermark Removal Performance (A) - 1 - TPR@0.1%FPR",
      "Image Quality Degradation (Q) - weighted aggregation of 8 IQMs"
    ],
    "higherIsBetter": false,
    "notes": "The final score is computed as the Euclidean distance in Q-A space: sqrt(Q^2 + A^2). Detection thresholds for A are pre-calibrated using 10,000 unwatermarked images per watermark type. Q aggregates eight IQMs (PSNR, SSIM, NMI, FID, CLIP-FID, LPIPS, ∆Aesthetics, ∆Artifacts) using a weighted formula."
  },

  "cr:execution": {
    "runtimeLimitSec": 2400,
    "memoryLimitMb": 4096,
    "allowedExternalData": "unknown"
  },

  "open_questions": [
    "Are participants allowed to use external data for training or fine-tuning their models?",
    "What is the exact format of the metadata provided for participant submissions (e.g., per-watermark scores, IQMs)?",
    "Are there any specific preprocessing steps required for the input images beyond what is described in the evaluation pipeline?"
  ],

  "fill_in_the_blank": [
    "cr:execution.allowedExternalData - The paper does not specify whether external data is allowed.",
    "cr:output.cr:schema.field[0].description - No specific examples of attacked images are provided in the paper.",
    "cr:evaluation.notes - The exact calibration process for detection thresholds is not described in detail."
  ]
}
